'use strict';(()=>{const key='michael-tv-remote-cursor',media=matchMedia('(min-width:1024px) and (pointer:fine) and (prefers-reduced-motion:no-preference)'),bar=document.querySelector('.tv-effects-control');if(!bar)return;const toggle=document.createElement('button');toggle.type='button';toggle.className='tv-remote-toggle';toggle.setAttribute('role','switch');toggle.setAttribute('aria-label','Remote cursor');toggle.innerHTML='<span class="tv-remote-switch" aria-hidden="true"><i></i></span><span>Remote cursor</span>';bar.append(toggle);const remote=document.createElement('div');remote.id='tv-remote-cursor';remote.setAttribute('aria-hidden','true');remote.innerHTML='<span class="tv-remote-body"><svg viewBox="0 0 40 48" width="40" height="48" aria-hidden="true"><rect class="tv-remote-ir" x="13" y="1" width="14" height="8" rx="4" fill="#c3a2ff"/><rect x="8" y="6" width="24" height="40" rx="8" fill="#181322" stroke="#a88bdf"/><circle class="tv-remote-power" cx="20" cy="15" r="4.3" fill="#d94c6a"/><path d="M20 12v4m-2-2a3 3 0 104 0" fill="none" stroke="white" stroke-width=".8"/><rect x="12" y="23" width="7" height="5" rx="2" fill="#a593c3"/><rect x="21" y="23" width="7" height="5" rx="2" fill="#a593c3"/><circle cx="16" cy="34" r="2" fill="#8e73d6"/><circle cx="24" cy="34" r="2" fill="#8e73d6"/></svg><span class="tv-remote-label">OK</span><span class="tv-remote-pulse"></span></span>';document.body.append(remote);const label=remote.querySelector('.tv-remote-label');let enabled=true;try{enabled=localStorage.getItem(key)!=='0'}catch{}let x=-100,y=-100,tx=-100,ty=-100,frame=0,visible=false,ready=false,drag=false,lastX=0;const hide=()=>{visible=false;document.documentElement.classList.remove('tv-remote-active');remote.classList.remove('is-visible','is-hover')};const refresh=()=>{ready=enabled&&media.matches;toggle.classList.toggle('is-on',enabled);toggle.setAttribute('aria-checked',String(enabled));if(!ready)hide()};const draw=()=>{frame=0;if(!visible)return;x+=(tx-x)*.22;y+=(ty-y)*.22;remote.style.transform=`translate3d(${x-20}px,${y-3}px,0)`;if(Math.abs(tx-x)+Math.abs(ty-y)>.12)frame=requestAnimationFrame(draw)};const update=e=>{if(!ready||(e.pointerType&&e.pointerType!=='mouse')){hide();return}const t=e.target,blocked=t.closest('input,textarea,select,[contenteditable], [role="textbox"]')||t.tagName==='IFRAME';if(blocked){hide();return}const dialog=document.querySelector('#mtv-intro[open]'),parent=dialog||document.body;if(remote.parentNode!==parent)parent.append(remote);tx=e.clientX;ty=e.clientY;if(drag){remote.style.setProperty('--remote-drag',e.clientX>=lastX?'8deg':'-8deg');lastX=e.clientX}if(!visible){visible=true;x=tx;y=ty;remote.style.transform=`translate3d(${x-20}px,${y-3}px,0)`;remote.classList.add('is-visible');document.documentElement.classList.add('tv-remote-active')}const hot=t.closest('a,button,[role="button"],[role="tab"],summary,.photo-carousel-rail figure');remote.classList.toggle('is-hover',!!hot);const nav=t.closest('#apple-navlinks a');label.textContent=nav?'CH '+String([...nav.parentElement.querySelectorAll('a')].indexOf(nav)+1).padStart(2,'0'):t.closest('#mtv-intro .mtv-play')?'PLAY':'OK';if(!frame)frame=requestAnimationFrame(draw)};document.addEventListener('pointermove',update,{capture:true,passive:true});document.addEventListener('pointerdown',e=>{if(!visible||e.pointerType!=='mouse')return;drag=!!e.target.closest('.photo-carousel-rail');lastX=e.clientX;remote.classList.toggle('is-dragging',drag);x=tx=e.clientX;y=ty=e.clientY;remote.style.transform=`translate3d(${x-20}px,${y-3}px,0)`;remote.classList.add('is-pressed');remote.classList.remove('is-pulsing');requestAnimationFrame(()=>remote.classList.add('is-pulsing'))},true);for(const name of['pointerup','pointercancel'])document.addEventListener(name,()=>{drag=false;remote.classList.remove('is-pressed','is-dragging')},true);document.addEventListener('pointerout',e=>{if(!e.relatedTarget)hide()},true);window.addEventListener('blur',hide);toggle.addEventListener('click',()=>{enabled=!enabled;try{localStorage.setItem(key,enabled?'1':'0')}catch{}refresh()});media.addEventListener?.('change',refresh);refresh();})();